import logging
from ute_common_converter.to_number import to_int


class BTSSMBaseError(Exception):
    """Base exception for ute_btssm package."""


class BTSSMExecutionError(BTSSMBaseError):
    """Exception raised when command execution fails."""
    def __init__(self, msg, out=None, rc=None, rc_only=False):
        self.rc = to_int(rc, skip_none=True)
        out = '' if out is None else '+++ Output +++\n{}\n\n'.format(out.strip())
        input_rc = '' if rc is None else '+++ Return Code +++\n{}\n\n'.format(rc.strip())

        tmp_msg = '{}\n\n{}{}'.format(msg, out, input_rc)
        if rc_only:
            msg = str(rc.strip())
            log = logging.getLogger(__name__)
            log.warning(tmp_msg)
        else:
            msg = tmp_msg
        super(BTSSMExecutionError, self).__init__(msg)


class CannotCheckBTSSMInstallerVersion(BTSSMBaseError):
    """Exception raised when BTS SM installer version cannot be established."""


class ScfcParsingError(BTSSMBaseError):
    """Exception raised when an SCFC file cannot be parsed or modified for some reason."""


class ScfcFixerError(BTSSMBaseError):
    """Exception raised when an SCFC file cannot be fixed for some reason."""


class ScfcValidationError(BTSSMBaseError):
    """Exception raised when a validation report contains error."""


class InvalidSwSource(BTSSMBaseError):
    """Exception raised during targetbd Parameter validation."""


class NonexistentBtssm(BTSSMBaseError):
    """Exception raised when Btssm is not installed"""


class ErrorFoundInCommandLineOutput(BTSSMBaseError):
    """Exception raised when command line output contains error string."""
    def __init__(self, search_result, out):
        out = '+++ Output +++\n{}\n\n'.format(out.strip())
        pattern = '+++ Used regexp pattern +++\n{}\n\n'.format(search_result.re.pattern) if hasattr(search_result, 're') else ''
        err = '+++ Found error string +++\n{}\n\n'.format(search_result.groups()[0]) if self._has_groups(search_result) else ''
        msg = 'Command line contains error string\n\n{}{}{}'.format(pattern, err, out)
        super(ErrorFoundInCommandLineOutput, self).__init__(msg)

    def _has_groups(self, search_result):
        return hasattr(search_result, 'groups') and search_result.groups()


class BTSSMJSONRequestError(BTSSMBaseError):
    """Exception raised when json operation fails."""


class RpcException(BTSSMBaseError):
    """ Exception raised when rpc operation fails"""
    def __init__(self, rpc_exception, message=''):
        self.rpc_exception = rpc_exception
        self.message = message

    def __str__(self):
        ret = ''
        if self.rpc_exception is not None:
            ret += str(self.rpc_exception)
        if self.message is not None:
            ret += ' | Message: ' + self.message
        return ret


class ToolLogParserException(BTSSMBaseError):
    """Exception raises when tool log parser fails"""


class FileCollectorException(Exception):
    """Exception raised if it was not possible to collect files."""


class CLIToolsMissing(BTSSMBaseError):
    """Exception raised if CLI Tools are missing. """


class MismatchIssuerAndSerialNumber(BTSSMBaseError):
    """Exception raised if issuer list length is not identical to serial number list length"""


class InvalidCertificateType(BTSSMBaseError):
    """Exception raised if Certificate Type provided does not exist"""
